    if (shortEFID != null) children.add(_asn1EncodeRaw(0x88, shortEFID!));
    if (proprietaryEFInfo != null)
      children.add((proprietaryEFInfo as dynamic).encode(tag: 0xA5));
    if (linkPath != null) children.add(_asn1EncodeRaw(0xC7, linkPath!));
