    Uint8List? efFileSize;
    Uint8List? pinStatusTemplateDO;
    Uint8List? shortEFID;
    ProprietaryInfo? proprietaryEFInfo;
    Uint8List? linkPath;
    int childIdx = 0;
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0x82) {
      final child = node!.children[childIdx];
      fileDescriptor = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0x83) {
