      fileID = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0x84) {
      final child = node!.children[childIdx];
      dfName = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      lcsi = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0x8B) {
      final child = node!.children[childIdx];
      securityAttributesReferenced = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0x80) {
