class KeyObject {
  final Uint8List? keyUsageQualifier;
  final Uint8List? keyAccess;
  final Uint8List? keyIdentifier;
  final Uint8List? keyVersionNumber;
  final Uint8List? keyCounterValue;
  final List<UInt8>? keyCompontents;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const KeyObject._({
    this.keyUsageQualifier,
    this.keyAccess,
    this.keyIdentifier,
    this.keyVersionNumber,
    this.keyCounterValue,
    this.keyCompontents,
    this.asn1,
  });

  const KeyObject({
    Uint8List? keyUsageQualifier,
    Uint8List? keyAccess,
    Uint8List? keyIdentifier,
    Uint8List? keyVersionNumber,
    Uint8List? keyCounterValue,
    List<UInt8>? keyCompontents,
  }) : this._(
         keyUsageQualifier: keyUsageQualifier,
         keyAccess: keyAccess,
         keyIdentifier: keyIdentifier,
         keyVersionNumber: keyVersionNumber,
         keyCounterValue: keyCounterValue,
         keyCompontents: keyCompontents,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (keyUsageQualifier != null)
      children.add(_asn1EncodeRaw(0x95, keyUsageQualifier!));
    if (keyAccess != null) children.add(_asn1EncodeRaw(0x96, keyAccess!));
    if (keyIdentifier != null)
      children.add(_asn1EncodeRaw(0x82, keyIdentifier!));
    if (keyVersionNumber != null)
      children.add(_asn1EncodeRaw(0x83, keyVersionNumber!));
    if (keyCounterValue != null)
      children.add(_asn1EncodeRaw(0x85, keyCounterValue!));
    if (keyCompontents != null) {
      final items = <Uint8List>[];
      for (final v in keyCompontents!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0x4, items));
    }
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory KeyObject.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    Uint8List? keyUsageQualifier;
    Uint8List? keyAccess;
    Uint8List? keyIdentifier;
    Uint8List? keyVersionNumber;
    Uint8List? keyCounterValue;
    List<UInt8>? keyCompontents;
    int childIdx = 0;
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      keyUsageQualifier = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      keyAccess = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      keyIdentifier = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      keyVersionNumber = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0x85) {
      final child = node!.children[childIdx];
      keyCounterValue = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <UInt8>[];
      for (final n in child.children) {
        items.add(n.value);
      }
      keyCompontents = items;
      childIdx++;
    }
    return KeyObject._(
      keyUsageQualifier: keyUsageQualifier,
      keyAccess: keyAccess,
      keyIdentifier: keyIdentifier,
      keyVersionNumber: keyVersionNumber,
      keyCounterValue: keyCounterValue,
      keyCompontents: keyCompontents,
      asn1: node, // Store original node
    );
