  static KeyObject decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return KeyObject.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return KeyObject.fromAsn1(node, tag: tag);
    }
    return KeyObject();
  }

  @override
  String toString() {
