      }
    }
    final keyAccessVal = keyAccess;
    if (keyAccessVal != null) {
      final val = keyAccessVal;
      if (val is Uint8List) {
        buffer.writeln('  keyAccess: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  keyAccess: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final keyIdentifierVal = keyIdentifier;
    if (keyIdentifierVal != null) {
      final val = keyIdentifierVal;
      if (val is Uint8List) {
        buffer.writeln('  keyIdentifier: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  keyIdentifier: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final keyVersionNumberVal = keyVersionNumber;
    if (keyVersionNumberVal != null) {
