class GeneralSubtree {
  final GeneralName? base;
  final BaseDistance? minimum;
  final BaseDistance? maximum;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const GeneralSubtree._({this.base, this.minimum, this.maximum, this.asn1});

  const GeneralSubtree({
    GeneralName? base,
    BaseDistance? minimum,
    BaseDistance? maximum,
  }) : this._(base: base, minimum: minimum, maximum: maximum, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (base != null) children.add((base as dynamic).encode());
    if (minimum != null) children.add(_asn1EncodeRaw(0x80, minimum!));
    if (maximum != null) children.add(_asn1EncodeRaw(0x81, maximum!));
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory GeneralSubtree.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    GeneralName? base;
    BaseDistance? minimum;
    BaseDistance? maximum;
    int childIdx = 0;
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      base = GeneralName.decode(child, tag: child.tag);
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      minimum = child.value;
      childIdx++;
    }
