        break;
      case 0x82:
        dNSName = String.fromCharCodes(node.value);
        break;
      case 0xA3:
        x400Address = ORAddress.decode(node, tag: 0xA3);
        break;
      case 0xA4:
        directoryName = Name.decode(node, tag: 0xA4);
        break;
      case 0xA5:
        ediPartyName = EDIPartyName.decode(node, tag: 0xA5);
        break;
      case 0x86:
        uniformResourceIdentifier = String.fromCharCodes(node.value);
        break;
      case 0x87:
        iPAddress = node.value;
        break;
      case 0x88:
        registeredID = node.value;
        break;
    }
    return GeneralName._(
      otherName: otherName,
      rfc822Name: rfc822Name,
      dNSName: dNSName,
      x400Address: x400Address,
      directoryName: directoryName,
      ediPartyName: ediPartyName,
      uniformResourceIdentifier: uniformResourceIdentifier,
      iPAddress: iPAddress,
      registeredID: registeredID,
      asn1: node, // Store original node
    );
  }

  static GeneralName decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return GeneralName.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return GeneralName.fromAsn1(node, tag: tag);
    }
    return GeneralName();
  }

  @override
