  static PE_OPT_CSIM decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return PE_OPT_CSIM.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return PE_OPT_CSIM.fromAsn1(node, tag: tag);
    }
    return PE_OPT_CSIM();
  }

