class ExtensionAttribute {
  final int? extension_attribute_type;
  final Uint8List? extension_attribute_value;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const ExtensionAttribute._({
    this.extension_attribute_type,
    this.extension_attribute_value,
    this.asn1,
  });

  const ExtensionAttribute({
    int? extension_attribute_type,
    Uint8List? extension_attribute_value,
  }) : this._(
         extension_attribute_type: extension_attribute_type,
         extension_attribute_value: extension_attribute_value,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (extension_attribute_type != null)
      children.add(
        _asn1EncodeRaw(0x80, _asn1EncodeInt(extension_attribute_type!)),
      );
    if (extension_attribute_value != null)
      children.add(_asn1EncodeRaw(0xA1, extension_attribute_value!));
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory ExtensionAttribute.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    int? extension_attribute_type;
    Uint8List? extension_attribute_value;
    int childIdx = 0;
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      extension_attribute_type = _asn1DecodeInt(child.value);
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      extension_attribute_value = child.value;
      childIdx++;
    }
    return ExtensionAttribute._(
      extension_attribute_type: extension_attribute_type,
      extension_attribute_value: extension_attribute_value,
      asn1: node, // Store original node
    );
  }

  static ExtensionAttribute decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return ExtensionAttribute.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return ExtensionAttribute.fromAsn1(node, tag: tag);
    }
    return ExtensionAttribute();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('ExtensionAttribute(');
    final extension_attribute_typeVal = extension_attribute_type;
    if (extension_attribute_typeVal != null) {
      final val = extension_attribute_typeVal;
      if (val is Uint8List) {
        buffer.writeln('  extension_attribute_type: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  extension_attribute_type: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final extension_attribute_valueVal = extension_attribute_value;
    if (extension_attribute_valueVal != null) {
      final val = extension_attribute_valueVal;
      if (val is Uint8List) {
        buffer.writeln('  extension_attribute_value: ${_hex(val)},');
