class PE_PINCodes_pinCodes {
  final List<PINConfiguration>? pinconfig;
  final Uint8List? filePath;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PE_PINCodes_pinCodes._({this.pinconfig, this.filePath, this.asn1});

  const PE_PINCodes_pinCodes({
    List<PINConfiguration>? pinconfig,
    Uint8List? filePath,
  }) : this._(pinconfig: pinconfig, filePath: filePath, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0xA1;
    if (pinconfig != null) {
      final items = <Uint8List>[];
      for (final v in pinconfig!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA0, items));
    }
    if (filePath != null) children.add(_asn1EncodeRaw(0x81, filePath!));
    if (tag != null) {
      return _asn1EncodeConstructed(tag, children);
    }
    return children.isNotEmpty ? children.first : Uint8List(0);
  }

  factory PE_PINCodes_pinCodes.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0xA1;
    if (node.tag != (tag ?? defaultTag)) {
      /* tag mismatch */
    }
    List<PINConfiguration>? pinconfig;
    Uint8List? filePath;
    for (final child in node!.children) {
      switch (child.tag) {
        case 0xA0:
          final items = <PINConfiguration>[];
          for (final n in child.children) {
            items.add(PINConfiguration.decode(n));
          }
          pinconfig = items;
          break;
        case 0x81:
          filePath = child.value;
          break;
      }
    }
    return PE_PINCodes_pinCodes._(
      pinconfig: pinconfig,
      filePath: filePath,
      asn1: node, // Store original node
    );
  }

  static PE_PINCodes_pinCodes decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return PE_PINCodes_pinCodes.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return PE_PINCodes_pinCodes.fromAsn1(node, tag: tag);
    }
    return PE_PINCodes_pinCodes();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PE_PINCodes_pinCodes(');
    final pinconfigVal = pinconfig;
    if (pinconfigVal != null) {
      final val = pinconfigVal;
      if (val is Uint8List) {
        buffer.writeln('  pinconfig: ${_hex(val)},');
      } else if (val is List) {
        buffer.writeln(
          '  pinconfig: [${val.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
        );
      } else {
        buffer.writeln(
          '  pinconfig: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final filePathVal = filePath;
    if (filePathVal != null) {
      final val = filePathVal;
      if (val is Uint8List) {
        buffer.writeln('  filePath: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  filePath: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    buffer.write(')');
    return buffer.toString();
  }
}

