    Uint8List? profileInstallationAborted,
    String? statusMessage,
  }) : this._(
         peStatus: peStatus,
         profileInstallationAborted: profileInstallationAborted,
         statusMessage: statusMessage,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (peStatus != null) {
      final items = <Uint8List>[];
      for (final v in peStatus!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA0, items));
    }
    if (profileInstallationAborted != null)
      children.add(_asn1EncodeRaw(0x81, profileInstallationAborted!));
    if (statusMessage != null)
      children.add(
        _asn1EncodeRaw(0x82, Uint8List.fromList(statusMessage!.codeUnits)),
      );
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

