class PE_PUKCodes {
  final PEHeader? puk_Header;
  final List<PUKConfiguration>? pukCodes;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PE_PUKCodes._({this.puk_Header, this.pukCodes, this.asn1});

  const PE_PUKCodes({PEHeader? puk_Header, List<PUKConfiguration>? pukCodes})
    : this._(puk_Header: puk_Header, pukCodes: pukCodes, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (puk_Header != null)
      children.add((puk_Header as dynamic).encode(tag: 0xA0));
    if (pukCodes != null) {
      final items = <Uint8List>[];
      for (final v in pukCodes!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA1, items));
    }
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory PE_PUKCodes.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    PEHeader? puk_Header;
    List<PUKConfiguration>? pukCodes;
    int childIdx = 0;
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      puk_Header = PEHeader.decode(child, tag: child.tag);
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <PUKConfiguration>[];
      for (final n in child.children) {
        items.add(PUKConfiguration.decode(n));
      }
      pukCodes = items;
      childIdx++;
    }
    return PE_PUKCodes._(
      puk_Header: puk_Header,
      pukCodes: pukCodes,
      asn1: node, // Store original node
    );
  }

  static PE_PUKCodes decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return PE_PUKCodes.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return PE_PUKCodes.fromAsn1(node, tag: tag);
    }
    return PE_PUKCodes();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PE_PUKCodes(');
    final puk_HeaderVal = puk_Header;
    if (puk_HeaderVal != null) {
      final val = puk_HeaderVal;
      if (val is Uint8List) {
        buffer.writeln('  puk_Header: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  puk_Header: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final pukCodesVal = pukCodes;
    if (pukCodesVal != null) {
      final val = pukCodesVal;
      if (val is Uint8List) {
        buffer.writeln('  pukCodes: ${_hex(val)},');
      } else if (val is List) {
        buffer.writeln(
          '  pukCodes: [${val.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
        );
      } else {
        buffer.writeln(
          '  pukCodes: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    buffer.write(')');
    return buffer.toString();
  }
