class PDSParameter {
  final String? printable_string;
  final String? teletex_string;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PDSParameter._({this.printable_string, this.teletex_string, this.asn1});

  const PDSParameter({String? printable_string, String? teletex_string})
    : this._(
        printable_string: printable_string,
        teletex_string: teletex_string,
        asn1: null,
      );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (printable_string != null)
      children.add(
        _asn1EncodeRaw(0xC, Uint8List.fromList(printable_string!.codeUnits)),
      );
    if (teletex_string != null)
      children.add(
        _asn1EncodeRaw(0xC, Uint8List.fromList(teletex_string!.codeUnits)),
      );
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory PDSParameter.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    String? printable_string;
    String? teletex_string;
    int childIdx = 0;
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0xC) {
      final child = node!.children[childIdx];
      printable_string = String.fromCharCodes(child.value);
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0xC) {
      final child = node!.children[childIdx];
      teletex_string = String.fromCharCodes(child.value);
      childIdx++;
    }
    return PDSParameter._(
      printable_string: printable_string,
      teletex_string: teletex_string,
      asn1: node, // Store original node
    );
  }

  static PDSParameter decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return PDSParameter.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return PDSParameter.fromAsn1(node, tag: tag);
    }
    return PDSParameter();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PDSParameter(');
    final printable_stringVal = printable_string;
    if (printable_stringVal != null) {
      final val = printable_stringVal;
      if (val is Uint8List) {
        buffer.writeln('  printable_string: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  printable_string: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final teletex_stringVal = teletex_string;
    if (teletex_stringVal != null) {
      final val = teletex_stringVal;
      if (val is Uint8List) {
        buffer.writeln('  teletex_string: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  teletex_string: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    buffer.write(')');
    return buffer.toString();
  }
