class PE_MF {
  final PEHeader? mf_header;
  final Uint8List? templateID;
  final File? mf;
  final File? ef_pl;
  final File? ef_iccid;
  final File? ef_dir;
  final File? ef_arr;
  final File? ef_umpc;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PE_MF._({
    this.mf_header,
    this.templateID,
    this.mf,
    this.ef_pl,
    this.ef_iccid,
    this.ef_dir,
    this.ef_arr,
    this.ef_umpc,
    this.asn1,
  });

  const PE_MF({
    PEHeader? mf_header,
    Uint8List? templateID,
    File? mf,
    File? ef_pl,
    File? ef_iccid,
    File? ef_dir,
    File? ef_arr,
    File? ef_umpc,
  }) : this._(
         mf_header: mf_header,
         templateID: templateID,
         mf: mf,
         ef_pl: ef_pl,
         ef_iccid: ef_iccid,
         ef_dir: ef_dir,
         ef_arr: ef_arr,
         ef_umpc: ef_umpc,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (mf_header != null)
      children.add((mf_header as dynamic).encode(tag: 0xA0));
    if (templateID != null) children.add(_asn1EncodeRaw(0x81, templateID!));
    if (mf != null) {
      final items = <Uint8List>[];
      for (final v in mf!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA2, items));
    }
    if (ef_pl != null) {
      final items = <Uint8List>[];
      for (final v in ef_pl!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA3, items));
    }
    if (ef_iccid != null) {
      final items = <Uint8List>[];
      for (final v in ef_iccid!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA4, items));
    }
    if (ef_dir != null) {
      final items = <Uint8List>[];
      for (final v in ef_dir!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA5, items));
    }
    if (ef_arr != null) {
      final items = <Uint8List>[];
      for (final v in ef_arr!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA6, items));
    }
    if (ef_umpc != null) {
      final items = <Uint8List>[];
      for (final v in ef_umpc!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA7, items));
    }
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory PE_MF.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    PEHeader? mf_header;
    Uint8List? templateID;
    File? mf;
    File? ef_pl;
    File? ef_iccid;
    File? ef_dir;
    File? ef_arr;
    File? ef_umpc;
    int childIdx = 0;
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      mf_header = PEHeader.decode(child, tag: child.tag);
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      templateID = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      mf = items;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0xA3) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      ef_pl = items;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      ef_iccid = items;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      ef_dir = items;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      ef_arr = items;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0xA7) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      ef_umpc = items;
      childIdx++;
    }
    return PE_MF._(
      mf_header: mf_header,
      templateID: templateID,
      mf: mf,
      ef_pl: ef_pl,
      ef_iccid: ef_iccid,
      ef_dir: ef_dir,
      ef_arr: ef_arr,
      ef_umpc: ef_umpc,
      asn1: node, // Store original node
    );
  }

  static PE_MF decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return PE_MF.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return PE_MF.fromAsn1(node, tag: tag);
    }
    return PE_MF();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PE_MF(');
    final mf_headerVal = mf_header;
    if (mf_headerVal != null) {
      final val = mf_headerVal;
      if (val is Uint8List) {
        buffer.writeln('  mf_header: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  mf_header: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final templateIDVal = templateID;
    if (templateIDVal != null) {
      final val = templateIDVal;
      if (val is Uint8List) {
        buffer.writeln('  templateID: ${_hex(val)},');
      } else {
        buffer.writeln(
