        );
      } else {
        buffer.writeln('  mf: ${val.toString().replaceAll("\n", "\n  ")},');
      }
    }
    final ef_plVal = ef_pl;
    if (ef_plVal != null) {
      final val = ef_plVal;
      if (val is Uint8List) {
        buffer.writeln('  ef_pl: ${_hex(val)},');
      } else if (val is List) {
        buffer.writeln(
          '  ef_pl: [${val.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
        );
      } else {
