    if (ecId != null) children.add(_asn1EncodeRaw(0x80, ecId!));
    if (smdsAddress != null)
      children.add(
        _asn1EncodeRaw(0x81, Uint8List.fromList(smdsAddress!.codeUnits)),
      );
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory CheckEventRequest.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0xBF46;
