          mappingParameter = MappingParameter.decode(child, tag: 0xA0);
          break;
        case 0xA1:
          algoParameter = AlgoParameter.decode(child, tag: 0xA1);
          break;
      }
    }
    return PE_AKAParameter_algoConfiguration._(
      mappingParameter: mappingParameter,
      algoParameter: algoParameter,
      asn1: node, // Store original node
    );
  }

  static PE_AKAParameter_algoConfiguration decode(dynamic data, {int? tag}) {
    if (data is Asn1Node)
      return PE_AKAParameter_algoConfiguration.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null)
        return PE_AKAParameter_algoConfiguration.fromAsn1(node, tag: tag);
    }
    return PE_AKAParameter_algoConfiguration();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PE_AKAParameter_algoConfiguration(');
    final mappingParameterVal = mappingParameter;
    if (mappingParameterVal != null) {
      final val = mappingParameterVal;
      if (val is Uint8List) {
        buffer.writeln('  mappingParameter: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  mappingParameter: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final algoParameterVal = algoParameter;
    if (algoParameterVal != null) {
      final val = algoParameterVal;
      if (val is Uint8List) {
        buffer.writeln('  algoParameter: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  algoParameter: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    buffer.write(')');
    return buffer.toString();
  }
}

