    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (contactless != null) children.add(_asn1EncodeRaw(0x80, contactless!));
    if (usim != null) children.add(_asn1EncodeRaw(0x81, usim!));
    if (isim != null) children.add(_asn1EncodeRaw(0x82, isim!));
    if (csim != null) children.add(_asn1EncodeRaw(0x83, csim!));
    if (milenage != null) children.add(_asn1EncodeRaw(0x84, milenage!));
    if (tuak128 != null) children.add(_asn1EncodeRaw(0x85, tuak128!));
    if (cave != null) children.add(_asn1EncodeRaw(0x86, cave!));
    if (gba_usim != null) children.add(_asn1EncodeRaw(0x87, gba_usim!));
    if (gba_isim != null) children.add(_asn1EncodeRaw(0x88, gba_isim!));
    if (mbms != null) children.add(_asn1EncodeRaw(0x89, mbms!));
    if (eap != null) children.add(_asn1EncodeRaw(0x8A, eap!));
    if (javacard != null) children.add(_asn1EncodeRaw(0x8B, javacard!));
    if (multos != null) children.add(_asn1EncodeRaw(0x8C, multos!));
    if (multiple_usim != null)
      children.add(_asn1EncodeRaw(0x8D, multiple_usim!));
    if (multiple_isim != null)
      children.add(_asn1EncodeRaw(0x8E, multiple_isim!));
    if (multiple_csim != null)
      children.add(_asn1EncodeRaw(0x8F, multiple_csim!));
    if (tuak256 != null) children.add(_asn1EncodeRaw(0x90, tuak256!));
    if (usim_test_algorithm != null)
      children.add(_asn1EncodeRaw(0x91, usim_test_algorithm!));
    if (ber_tlv != null) children.add(_asn1EncodeRaw(0x92, ber_tlv!));
    if (dfLink != null) children.add(_asn1EncodeRaw(0x93, dfLink!));
    if (cat_tp != null) children.add(_asn1EncodeRaw(0x94, cat_tp!));
    if (get_identity != null) children.add(_asn1EncodeRaw(0x95, get_identity!));
    if (profile_a_x25519 != null)
      children.add(_asn1EncodeRaw(0x96, profile_a_x25519!));
    if (profile_b_p256 != null)
      children.add(_asn1EncodeRaw(0x97, profile_b_p256!));
    if (suciCalculatorApi != null)
      children.add(_asn1EncodeRaw(0x98, suciCalculatorApi!));
    if (dns_resolution != null)
      children.add(_asn1EncodeRaw(0x99, dns_resolution!));
    if (scp11ac != null) children.add(_asn1EncodeRaw(0x9A, scp11ac!));
    if (scp11c_authorization_mechanism != null)
      children.add(_asn1EncodeRaw(0x9B, scp11c_authorization_mechanism!));
    if (s16mode != null) children.add(_asn1EncodeRaw(0x9C, s16mode!));
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

