    if (eventType != null)
      children.add(_asn1EncodeRaw(0x82, _asn1EncodeInt(eventType!)));
    if (hashedIccids != null) {
      final items = <Uint8List>[];
      for (final v in hashedIccids!) {
        items.add(_asn1EncodeRaw(0x04, v));
      }
      children.add(_asn1EncodeConstructed(0xA3, items));
    }
    if (salt != null) children.add(_asn1EncodeRaw(0x84, salt!));
    if (serviceProviderName != null)
      children.add(
        _asn1EncodeRaw(
          0x91,
          Uint8List.fromList(serviceProviderName!.codeUnits),
        ),
      );
    if (operatorId != null)
      children.add((operatorId as dynamic).encode(tag: 0xB7));
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
