  final String? iso_3166_alpha2_code;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const CountryName._({
    this.x121_dcc_code,
    this.iso_3166_alpha2_code,
    this.asn1,
  });

  const CountryName({String? x121_dcc_code, String? iso_3166_alpha2_code})
    : this._(
        x121_dcc_code: x121_dcc_code,
        iso_3166_alpha2_code: iso_3166_alpha2_code,
        asn1: null,
      );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x61;
    if (x121_dcc_code != null)
      children.add(
        _asn1EncodeRaw(0xC, Uint8List.fromList(x121_dcc_code!.codeUnits)),
      );
    if (iso_3166_alpha2_code != null)
      children.add(
        _asn1EncodeRaw(
          0xC,
          Uint8List.fromList(iso_3166_alpha2_code!.codeUnits),
        ),
      );
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory CountryName.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x61;
    if (node.tag != (tag ?? defaultTag)) {
      /* tag mismatch */
    }
    String? x121_dcc_code;
    String? iso_3166_alpha2_code;
    for (final child in node!.children) {
      switch (child.tag) {
        case 0xC:
          x121_dcc_code = String.fromCharCodes(child.value);
          break;
        case 0xC:
          iso_3166_alpha2_code = String.fromCharCodes(child.value);
          break;
      }
    }
    return CountryName._(
      x121_dcc_code: x121_dcc_code,
      iso_3166_alpha2_code: iso_3166_alpha2_code,
      asn1: node, // Store original node
    );
  }

  static CountryName decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return CountryName.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return CountryName.fromAsn1(node, tag: tag);
    }
    return CountryName();
  }

  @override
  String toString() {
    if (x121_dcc_code != null) return x121_dcc_code!;
    if (iso_3166_alpha2_code != null) return iso_3166_alpha2_code!;
    return 'CountryName()';
  }
}

