class PINConfiguration {
  final PINKeyReferenceValue? keyReference;
  final Uint8List? pinValue;
  final PUKKeyReferenceValue? unblockingPINReference;
  final UInt8? pinAttributes;
  final UInt8? maxNumOfAttemps_retryNumLeft;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PINConfiguration._({
    this.keyReference,
    this.pinValue,
    this.unblockingPINReference,
    this.pinAttributes,
    this.maxNumOfAttemps_retryNumLeft,
    this.asn1,
  });

  const PINConfiguration({
    PINKeyReferenceValue? keyReference,
    Uint8List? pinValue,
    PUKKeyReferenceValue? unblockingPINReference,
    UInt8? pinAttributes,
    UInt8? maxNumOfAttemps_retryNumLeft,
  }) : this._(
         keyReference: keyReference,
         pinValue: pinValue,
         unblockingPINReference: unblockingPINReference,
         pinAttributes: pinAttributes,
         maxNumOfAttemps_retryNumLeft: maxNumOfAttemps_retryNumLeft,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (keyReference != null)
      children.add(_asn1EncodeRaw(0x80, _asn1EncodeInt(keyReference!.value)));
    if (pinValue != null) children.add(_asn1EncodeRaw(0x81, pinValue!));
    if (unblockingPINReference != null)
      children.add(
        _asn1EncodeRaw(0x82, _asn1EncodeInt(unblockingPINReference!.value)),
      );
    if (pinAttributes != null)
      children.add(_asn1EncodeRaw(0x83, pinAttributes!));
    if (maxNumOfAttemps_retryNumLeft != null)
      children.add(_asn1EncodeRaw(0x84, maxNumOfAttemps_retryNumLeft!));
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory PINConfiguration.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    PINKeyReferenceValue? keyReference;
    Uint8List? pinValue;
    PUKKeyReferenceValue? unblockingPINReference;
    UInt8? pinAttributes;
    UInt8? maxNumOfAttemps_retryNumLeft;
    int childIdx = 0;
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      keyReference = PINKeyReferenceValueExt.fromValue(
        _asn1DecodeInt(child.value),
      );
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      pinValue = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0x82) {
      final child = node!.children[childIdx];
      unblockingPINReference = PUKKeyReferenceValueExt.fromValue(
        _asn1DecodeInt(child.value),
      );
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      pinAttributes = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      maxNumOfAttemps_retryNumLeft = child.value;
      childIdx++;
    }
    return PINConfiguration._(
      keyReference: keyReference,
      pinValue: pinValue,
      unblockingPINReference: unblockingPINReference,
      pinAttributes: pinAttributes,
      maxNumOfAttemps_retryNumLeft: maxNumOfAttemps_retryNumLeft,
      asn1: node, // Store original node
    );
  }

  static PINConfiguration decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return PINConfiguration.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return PINConfiguration.fromAsn1(node, tag: tag);
    }
    return PINConfiguration();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PINConfiguration(');
    final keyReferenceVal = keyReference;
    if (keyReferenceVal != null) {
      final val = keyReferenceVal;
      if (val is Uint8List) {
        buffer.writeln('  keyReference: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  keyReference: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final pinValueVal = pinValue;
    if (pinValueVal != null) {
      final val = pinValueVal;
      if (val is Uint8List) {
        buffer.writeln('  pinValue: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  pinValue: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final unblockingPINReferenceVal = unblockingPINReference;
    if (unblockingPINReferenceVal != null) {
      final val = unblockingPINReferenceVal;
      if (val is Uint8List) {
        buffer.writeln('  unblockingPINReference: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  unblockingPINReference: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final pinAttributesVal = pinAttributes;
    if (pinAttributesVal != null) {
      final val = pinAttributesVal;
      if (val is Uint8List) {
        buffer.writeln('  pinAttributes: ${_hex(val)},');
      } else {
        buffer.writeln(
