    this.bmpString,
    this.asn1,
  });

  const X520Pseudonym({
    String? teletexString,
    String? printableString,
    String? universalString,
    String? utf8String,
    String? bmpString,
  }) : this._(
         teletexString: teletexString,
         printableString: printableString,
         universalString: universalString,
         utf8String: utf8String,
         bmpString: bmpString,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (teletexString != null)
      children.add(
        _asn1EncodeRaw(0xC, Uint8List.fromList(teletexString!.codeUnits)),
      );
    if (printableString != null)
      children.add(
        _asn1EncodeRaw(0xC, Uint8List.fromList(printableString!.codeUnits)),
      );
    if (universalString != null)
      children.add(
        _asn1EncodeRaw(0xC, Uint8List.fromList(universalString!.codeUnits)),
      );
    if (utf8String != null)
      children.add(
        _asn1EncodeRaw(0xC, Uint8List.fromList(utf8String!.codeUnits)),
      );
    if (bmpString != null)
      children.add(
        _asn1EncodeRaw(0xC, Uint8List.fromList(bmpString!.codeUnits)),
      );
    if (tag != null) {
      return _asn1EncodeConstructed(tag, children);
    }
    return children.isNotEmpty ? children.first : Uint8List(0);
  }

  factory X520Pseudonym.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    String? teletexString;
    String? printableString;
    String? universalString;
    String? utf8String;
    String? bmpString;
    // CHOICE: check node's tag directly
    switch (node!.tag) {
      case 0xC:
        teletexString = String.fromCharCodes(node.value);
        break;
      case 0xC:
        printableString = String.fromCharCodes(node.value);
        break;
      case 0xC:
        universalString = String.fromCharCodes(node.value);
        break;
      case 0xC:
        utf8String = String.fromCharCodes(node.value);
        break;
      case 0xC:
        bmpString = String.fromCharCodes(node.value);
        break;
    }
    return X520Pseudonym._(
      teletexString: teletexString,
      printableString: printableString,
      universalString: universalString,
      utf8String: utf8String,
      bmpString: bmpString,
      asn1: node, // Store original node
    );
  }

  static X520Pseudonym decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return X520Pseudonym.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return X520Pseudonym.fromAsn1(node, tag: tag);
    }
    return X520Pseudonym();
  }

  @override
  String toString() {
    if (teletexString != null) return teletexString!;
    if (printableString != null) return printableString!;
    if (universalString != null) return universalString!;
    if (utf8String != null) return utf8String!;
    if (bmpString != null) return bmpString!;
    return 'X520Pseudonym()';
  }
