    if (smdpOtpk != null) children.add(_asn1EncodeRaw(0x5F49, smdpOtpk!));
    if (smdpSign != null) children.add(_asn1EncodeRaw(0x5F37, smdpSign!));
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
