class Certificate {
  final TBSCertificate? tbsCertificate;
  final AlgorithmIdentifier? signatureAlgorithm;
  final int? signature;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const Certificate._({
