  static LoadRpmPackageRequest decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return LoadRpmPackageRequest.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return LoadRpmPackageRequest.fromAsn1(node, tag: tag);
    }
    return LoadRpmPackageRequest();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('LoadRpmPackageRequest(');
    final smdpSigned3Val = smdpSigned3;
    if (smdpSigned3Val != null) {
