    if (sSelector != null) children.add(_asn1EncodeRaw(0xA1, sSelector!));
    if (tSelector != null) children.add(_asn1EncodeRaw(0xA2, tSelector!));
    if (nAddresses != null) {
      final items = <Uint8List>[];
      for (final v in nAddresses!) {
        items.add(_asn1EncodeRaw(0x04, v));
      }
      children.add(_asn1EncodeConstructed(0xA3, items));
    }
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
