    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0xA1) {
      final child = node!.children[childIdx];
      sSelector = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0xA2) {
      final child = node!.children[childIdx];
      tSelector = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <Uint8List>[];
      for (final n in child.children) {
        items.add(n.value);
      }
      nAddresses = items;
      childIdx++;
    }
    return PresentationAddress._(
      pSelector: pSelector,
      sSelector: sSelector,
      tSelector: tSelector,
      nAddresses: nAddresses,
      asn1: node, // Store original node
