class AlertData {
  final MetadataUpdateEnabledProfile? metadataUpdateEnabledProfile;
  final ServerWithPendingOperation? pendingOperationAlert;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const AlertData._({
    this.metadataUpdateEnabledProfile,
    this.pendingOperationAlert,
    this.asn1,
  });

  const AlertData({
    MetadataUpdateEnabledProfile? metadataUpdateEnabledProfile,
    ServerWithPendingOperation? pendingOperationAlert,
  }) : this._(
         metadataUpdateEnabledProfile: metadataUpdateEnabledProfile,
         pendingOperationAlert: pendingOperationAlert,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0xBF4A;
    if (metadataUpdateEnabledProfile != null)
      children.add((metadataUpdateEnabledProfile as dynamic).encode(tag: 0xA0));
    if (pendingOperationAlert != null)
      children.add((pendingOperationAlert as dynamic).encode(tag: 0xA1));
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory AlertData.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0xBF4A;
    if (node.tag != (tag ?? defaultTag)) {
      /* tag mismatch */
    }
    MetadataUpdateEnabledProfile? metadataUpdateEnabledProfile;
    ServerWithPendingOperation? pendingOperationAlert;
    for (final child in node!.children) {
      switch (child.tag) {
        case 0xA0:
          metadataUpdateEnabledProfile = MetadataUpdateEnabledProfile.decode(
            child,
            tag: 0xA0,
          );
          break;
        case 0xA1:
          pendingOperationAlert = ServerWithPendingOperation.decode(
            child,
            tag: 0xA1,
          );
          break;
      }
    }
    return AlertData._(
      metadataUpdateEnabledProfile: metadataUpdateEnabledProfile,
      pendingOperationAlert: pendingOperationAlert,
      asn1: node, // Store original node
    );
  }

  static AlertData decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return AlertData.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return AlertData.fromAsn1(node, tag: tag);
    }
    return AlertData();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('AlertData(');
    final metadataUpdateEnabledProfileVal = metadataUpdateEnabledProfile;
    if (metadataUpdateEnabledProfileVal != null) {
      final val = metadataUpdateEnabledProfileVal;
      if (val is Uint8List) {
        buffer.writeln('  metadataUpdateEnabledProfile: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  metadataUpdateEnabledProfile: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final pendingOperationAlertVal = pendingOperationAlert;
    if (pendingOperationAlertVal != null) {
      final val = pendingOperationAlertVal;
      if (val is Uint8List) {
        buffer.writeln('  pendingOperationAlert: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  pendingOperationAlert: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    buffer.write(')');
    return buffer.toString();
  }
}

