class PUKConfiguration {
  final PUKKeyReferenceValue? keyReference;
  final Uint8List? pukValue;
  final UInt8? maxNumOfAttemps_retryNumLeft;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PUKConfiguration._({
    this.keyReference,
    this.pukValue,
    this.maxNumOfAttemps_retryNumLeft,
    this.asn1,
  });

  const PUKConfiguration({
    PUKKeyReferenceValue? keyReference,
    Uint8List? pukValue,
    UInt8? maxNumOfAttemps_retryNumLeft,
  }) : this._(
         keyReference: keyReference,
         pukValue: pukValue,
         maxNumOfAttemps_retryNumLeft: maxNumOfAttemps_retryNumLeft,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (keyReference != null)
      children.add(_asn1EncodeRaw(0x80, _asn1EncodeInt(keyReference!.value)));
    if (pukValue != null) children.add(_asn1EncodeRaw(0x81, pukValue!));
    if (maxNumOfAttemps_retryNumLeft != null)
      children.add(_asn1EncodeRaw(0x82, maxNumOfAttemps_retryNumLeft!));
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory PUKConfiguration.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    PUKKeyReferenceValue? keyReference;
    Uint8List? pukValue;
    UInt8? maxNumOfAttemps_retryNumLeft;
    int childIdx = 0;
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      keyReference = PUKKeyReferenceValueExt.fromValue(
        _asn1DecodeInt(child.value),
      );
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      pukValue = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      maxNumOfAttemps_retryNumLeft = child.value;
      childIdx++;
    }
    return PUKConfiguration._(
      keyReference: keyReference,
      pukValue: pukValue,
      maxNumOfAttemps_retryNumLeft: maxNumOfAttemps_retryNumLeft,
      asn1: node, // Store original node
    );
  }

  static PUKConfiguration decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return PUKConfiguration.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return PUKConfiguration.fromAsn1(node, tag: tag);
    }
    return PUKConfiguration();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PUKConfiguration(');
    final keyReferenceVal = keyReference;
    if (keyReferenceVal != null) {
      final val = keyReferenceVal;
      if (val is Uint8List) {
        buffer.writeln('  keyReference: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  keyReference: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final pukValueVal = pukValue;
    if (pukValueVal != null) {
      final val = pukValueVal;
      if (val is Uint8List) {
        buffer.writeln('  pukValue: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  pukValue: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final maxNumOfAttemps_retryNumLeftVal = maxNumOfAttemps_retryNumLeft;
    if (maxNumOfAttemps_retryNumLeftVal != null) {
      final val = maxNumOfAttemps_retryNumLeftVal;
      if (val is Uint8List) {
        buffer.writeln('  maxNumOfAttemps_retryNumLeft: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  maxNumOfAttemps_retryNumLeft: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class AlgorithmIdentifier {
  final Uint8List? algorithm;
  final Uint8List? parameters;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const AlgorithmIdentifier._({this.algorithm, this.parameters, this.asn1});

  const AlgorithmIdentifier({Uint8List? algorithm, Uint8List? parameters})
    : this._(algorithm: algorithm, parameters: parameters, asn1: null);

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (algorithm != null) children.add(_asn1EncodeRaw(0x4, algorithm!));
    if (parameters != null) children.add(_asn1EncodeRaw(0x4, parameters!));
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory AlgorithmIdentifier.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    Uint8List? algorithm;
    Uint8List? parameters;
    int childIdx = 0;
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      algorithm = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0x4) {
      final child = node!.children[childIdx];
      parameters = child.value;
      childIdx++;
    }
    return AlgorithmIdentifier._(
      algorithm: algorithm,
      parameters: parameters,
      asn1: node, // Store original node
    );
  }

  static AlgorithmIdentifier decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return AlgorithmIdentifier.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return AlgorithmIdentifier.fromAsn1(node, tag: tag);
    }
    return AlgorithmIdentifier();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('AlgorithmIdentifier(');
    final algorithmVal = algorithm;
    if (algorithmVal != null) {
      final val = algorithmVal;
      if (val is Uint8List) {
        buffer.writeln('  algorithm: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  algorithm: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final parametersVal = parameters;
    if (parametersVal != null) {
      final val = parametersVal;
      if (val is Uint8List) {
        buffer.writeln('  parameters: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  parameters: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class PE_ISIM {
  final PEHeader? isim_header;
  final Uint8List? templateID;
  final File? adf_isim;
  final File? ef_impi;
  final File? ef_impu;
  final File? ef_domain;
  final File? ef_ist;
  final File? ef_ad;
  final File? ef_arr;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const PE_ISIM._({
    this.isim_header,
    this.templateID,
    this.adf_isim,
    this.ef_impi,
    this.ef_impu,
    this.ef_domain,
    this.ef_ist,
    this.ef_ad,
    this.ef_arr,
    this.asn1,
  });

  const PE_ISIM({
    PEHeader? isim_header,
    Uint8List? templateID,
    File? adf_isim,
    File? ef_impi,
    File? ef_impu,
    File? ef_domain,
    File? ef_ist,
    File? ef_ad,
    File? ef_arr,
  }) : this._(
         isim_header: isim_header,
         templateID: templateID,
         adf_isim: adf_isim,
         ef_impi: ef_impi,
         ef_impu: ef_impu,
         ef_domain: ef_domain,
         ef_ist: ef_ist,
         ef_ad: ef_ad,
         ef_arr: ef_arr,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (isim_header != null)
      children.add((isim_header as dynamic).encode(tag: 0xA0));
    if (templateID != null) children.add(_asn1EncodeRaw(0x81, templateID!));
    if (adf_isim != null) {
      final items = <Uint8List>[];
      for (final v in adf_isim!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA2, items));
    }
    if (ef_impi != null) {
      final items = <Uint8List>[];
      for (final v in ef_impi!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA3, items));
    }
    if (ef_impu != null) {
      final items = <Uint8List>[];
      for (final v in ef_impu!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA4, items));
    }
    if (ef_domain != null) {
      final items = <Uint8List>[];
      for (final v in ef_domain!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA5, items));
    }
    if (ef_ist != null) {
      final items = <Uint8List>[];
      for (final v in ef_ist!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA6, items));
    }
    if (ef_ad != null) {
      final items = <Uint8List>[];
      for (final v in ef_ad!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA7, items));
    }
    if (ef_arr != null) {
      final items = <Uint8List>[];
      for (final v in ef_arr!) {
        items.add((v as dynamic).encode(tag: 0x30));
      }
      children.add(_asn1EncodeConstructed(0xA8, items));
    }
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory PE_ISIM.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    PEHeader? isim_header;
    Uint8List? templateID;
    File? adf_isim;
    File? ef_impi;
    File? ef_impu;
    File? ef_domain;
    File? ef_ist;
    File? ef_ad;
    File? ef_arr;
    int childIdx = 0;
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      isim_header = PEHeader.decode(child, tag: child.tag);
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      templateID = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      adf_isim = items;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      ef_impi = items;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      ef_impu = items;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      ef_domain = items;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      ef_ist = items;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0xA7) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      ef_ad = items;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <PEHeader>[];
      for (final n in child.children) {
        items.add(PEHeader.decode(n));
      }
      ef_arr = items;
      childIdx++;
    }
    return PE_ISIM._(
      isim_header: isim_header,
      templateID: templateID,
      adf_isim: adf_isim,
      ef_impi: ef_impi,
      ef_impu: ef_impu,
      ef_domain: ef_domain,
      ef_ist: ef_ist,
      ef_ad: ef_ad,
      ef_arr: ef_arr,
      asn1: node, // Store original node
    );
  }

  static PE_ISIM decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return PE_ISIM.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return PE_ISIM.fromAsn1(node, tag: tag);
    }
    return PE_ISIM();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('PE_ISIM(');
    final isim_headerVal = isim_header;
    if (isim_headerVal != null) {
      final val = isim_headerVal;
      if (val is Uint8List) {
        buffer.writeln('  isim_header: ${_hex(val)},');
      } else {
