    if (data is Asn1Node) return DistributionPointName.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return DistributionPointName.fromAsn1(node, tag: tag);
    }
    return DistributionPointName();
  }

  @override
