      final val = extnIDVal;
      if (val is Uint8List) {
        buffer.writeln('  extnID: ${_hex(val)},');
      } else {
        buffer.writeln('  extnID: ${val.toString().replaceAll("\n", "\n  ")},');
      }
    }
    final criticalVal = critical;
    if (criticalVal != null) {
      final val = criticalVal;
      if (val is Uint8List) {
        buffer.writeln('  critical: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  critical: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final extnValueVal = extnValue;
    if (extnValueVal != null) {
      final val = extnValueVal;
      if (val is Uint8List) {
        buffer.writeln('  extnValue: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  extnValue: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    buffer.write(')');
    return buffer.toString();
  }
}

class ApplicationInstance {
  final ApplicationIdentifier? applicationLoadPackageAID;
  final ApplicationIdentifier? classAID;
  final ApplicationIdentifier? instanceAID;
  final ApplicationIdentifier? extraditeSecurityDomainAID;
  final Uint8List? applicationPrivileges;
  final Uint8List? lifeCycleState;
  final Uint8List? applicationSpecificParametersC9;
  final ApplicationSystemParameters? systemSpecificParameters;
  final UICCApplicationParameters? applicationParameters;
  final List<Uint8List>? processData;
  final ControlReferenceTemplate? controlReferenceTemplate;
  final Asn1Node? asn1; // Original ASN.1 node for byte-perfect re-encoding

  const ApplicationInstance._({
    this.applicationLoadPackageAID,
    this.classAID,
    this.instanceAID,
    this.extraditeSecurityDomainAID,
    this.applicationPrivileges,
    this.lifeCycleState,
    this.applicationSpecificParametersC9,
    this.systemSpecificParameters,
    this.applicationParameters,
    this.processData,
    this.controlReferenceTemplate,
    this.asn1,
  });

  const ApplicationInstance({
    ApplicationIdentifier? applicationLoadPackageAID,
    ApplicationIdentifier? classAID,
    ApplicationIdentifier? instanceAID,
    ApplicationIdentifier? extraditeSecurityDomainAID,
    Uint8List? applicationPrivileges,
    Uint8List? lifeCycleState,
    Uint8List? applicationSpecificParametersC9,
    ApplicationSystemParameters? systemSpecificParameters,
    UICCApplicationParameters? applicationParameters,
    List<Uint8List>? processData,
    ControlReferenceTemplate? controlReferenceTemplate,
  }) : this._(
         applicationLoadPackageAID: applicationLoadPackageAID,
         classAID: classAID,
         instanceAID: instanceAID,
         extraditeSecurityDomainAID: extraditeSecurityDomainAID,
         applicationPrivileges: applicationPrivileges,
         lifeCycleState: lifeCycleState,
         applicationSpecificParametersC9: applicationSpecificParametersC9,
         systemSpecificParameters: systemSpecificParameters,
         applicationParameters: applicationParameters,
         processData: processData,
         controlReferenceTemplate: controlReferenceTemplate,
         asn1: null,
       );

  Uint8List encode({int? tag}) {
    // If we have the original ASN.1 node, re-encode it for byte-perfect output
    if (asn1 != null) {
      return asn1!.encodedBytes;
    }
    final children = <Uint8List>[];
    final defaultTag = 0x30;
    if (applicationLoadPackageAID != null)
      children.add(_asn1EncodeRaw(0x4F, applicationLoadPackageAID!));
    if (classAID != null) children.add(_asn1EncodeRaw(0x4F, classAID!));
    if (instanceAID != null) children.add(_asn1EncodeRaw(0x4F, instanceAID!));
    if (extraditeSecurityDomainAID != null)
      children.add(_asn1EncodeRaw(0x4F, extraditeSecurityDomainAID!));
    if (applicationPrivileges != null)
      children.add(_asn1EncodeRaw(0x82, applicationPrivileges!));
    if (lifeCycleState != null)
      children.add(_asn1EncodeRaw(0x83, lifeCycleState!));
    if (applicationSpecificParametersC9 != null)
      children.add(_asn1EncodeRaw(0xC9, applicationSpecificParametersC9!));
    if (systemSpecificParameters != null)
      children.add((systemSpecificParameters as dynamic).encode(tag: 0xEF));
    if (applicationParameters != null)
      children.add((applicationParameters as dynamic).encode(tag: 0xEA));
    if (processData != null) {
      final items = <Uint8List>[];
      for (final v in processData!) {
        items.add(_asn1EncodeRaw(0x04, v));
      }
      children.add(_asn1EncodeConstructed(0x4, items));
    }
    if (controlReferenceTemplate != null)
      children.add((controlReferenceTemplate as dynamic).encode(tag: 0xB0));
    return _asn1EncodeConstructed(tag ?? defaultTag, children);
  }

  factory ApplicationInstance.fromAsn1(Asn1Node node, {int? tag}) {
    final defaultTag = 0x30;
    ApplicationIdentifier? applicationLoadPackageAID;
    ApplicationIdentifier? classAID;
    ApplicationIdentifier? instanceAID;
    ApplicationIdentifier? extraditeSecurityDomainAID;
    Uint8List? applicationPrivileges;
    Uint8List? lifeCycleState;
    Uint8List? applicationSpecificParametersC9;
    ApplicationSystemParameters? systemSpecificParameters;
    UICCApplicationParameters? applicationParameters;
    List<Uint8List>? processData;
    ControlReferenceTemplate? controlReferenceTemplate;
    int childIdx = 0;
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      applicationLoadPackageAID = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      classAID = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      instanceAID = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0x4F) {
      final child = node!.children[childIdx];
      extraditeSecurityDomainAID = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      applicationPrivileges = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      lifeCycleState = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      applicationSpecificParametersC9 = child.value;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0xEF) {
      final child = node!.children[childIdx];
      systemSpecificParameters = ApplicationSystemParameters.decode(
        child,
        tag: child.tag,
      );
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0xEA) {
      final child = node!.children[childIdx];
      applicationParameters = UICCApplicationParameters.decode(
        child,
        tag: child.tag,
      );
      childIdx++;
    }
    if (childIdx < node!.children.length) {
      final child = node!.children[childIdx];
      final items = <Uint8List>[];
      for (final n in child.children) {
        items.add(n.value);
      }
      processData = items;
      childIdx++;
    }
    if (childIdx < node!.children.length &&
        node!.children[childIdx].tag == 0xB0) {
      final child = node!.children[childIdx];
      controlReferenceTemplate = ControlReferenceTemplate.decode(
        child,
        tag: child.tag,
      );
      childIdx++;
    }
    return ApplicationInstance._(
      applicationLoadPackageAID: applicationLoadPackageAID,
      classAID: classAID,
      instanceAID: instanceAID,
      extraditeSecurityDomainAID: extraditeSecurityDomainAID,
      applicationPrivileges: applicationPrivileges,
      lifeCycleState: lifeCycleState,
      applicationSpecificParametersC9: applicationSpecificParametersC9,
      systemSpecificParameters: systemSpecificParameters,
      applicationParameters: applicationParameters,
      processData: processData,
      controlReferenceTemplate: controlReferenceTemplate,
      asn1: node, // Store original node
    );
  }

  static ApplicationInstance decode(dynamic data, {int? tag}) {
    if (data is Asn1Node) return ApplicationInstance.fromAsn1(data, tag: tag);
    if (data is Uint8List) {
      final node = SimpleAsn1Reader(data).readNext();
      if (node != null) return ApplicationInstance.fromAsn1(node, tag: tag);
    }
    return ApplicationInstance();
  }

  @override
  String toString() {
    final buffer = StringBuffer();
    buffer.writeln('ApplicationInstance(');
    final applicationLoadPackageAIDVal = applicationLoadPackageAID;
    if (applicationLoadPackageAIDVal != null) {
      final val = applicationLoadPackageAIDVal;
      if (val is Uint8List) {
        buffer.writeln('  applicationLoadPackageAID: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  applicationLoadPackageAID: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final classAIDVal = classAID;
    if (classAIDVal != null) {
      final val = classAIDVal;
      if (val is Uint8List) {
        buffer.writeln('  classAID: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  classAID: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final instanceAIDVal = instanceAID;
    if (instanceAIDVal != null) {
      final val = instanceAIDVal;
      if (val is Uint8List) {
        buffer.writeln('  instanceAID: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  instanceAID: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final extraditeSecurityDomainAIDVal = extraditeSecurityDomainAID;
    if (extraditeSecurityDomainAIDVal != null) {
      final val = extraditeSecurityDomainAIDVal;
      if (val is Uint8List) {
        buffer.writeln('  extraditeSecurityDomainAID: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  extraditeSecurityDomainAID: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final applicationPrivilegesVal = applicationPrivileges;
    if (applicationPrivilegesVal != null) {
      final val = applicationPrivilegesVal;
      if (val is Uint8List) {
        buffer.writeln('  applicationPrivileges: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  applicationPrivileges: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final lifeCycleStateVal = lifeCycleState;
    if (lifeCycleStateVal != null) {
      final val = lifeCycleStateVal;
      if (val is Uint8List) {
        buffer.writeln('  lifeCycleState: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  lifeCycleState: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final applicationSpecificParametersC9Val = applicationSpecificParametersC9;
    if (applicationSpecificParametersC9Val != null) {
      final val = applicationSpecificParametersC9Val;
      if (val is Uint8List) {
        buffer.writeln('  applicationSpecificParametersC9: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  applicationSpecificParametersC9: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final systemSpecificParametersVal = systemSpecificParameters;
    if (systemSpecificParametersVal != null) {
      final val = systemSpecificParametersVal;
      if (val is Uint8List) {
        buffer.writeln('  systemSpecificParameters: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  systemSpecificParameters: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final applicationParametersVal = applicationParameters;
    if (applicationParametersVal != null) {
      final val = applicationParametersVal;
      if (val is Uint8List) {
        buffer.writeln('  applicationParameters: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  applicationParameters: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final processDataVal = processData;
    if (processDataVal != null) {
      final val = processDataVal;
      if (val is Uint8List) {
        buffer.writeln('  processData: ${_hex(val)},');
      } else if (val is List) {
        buffer.writeln(
          '  processData: [${val.map((e) => e.toString().replaceAll("\n", "\n  ")).join(", ")}],',
        );
      } else {
        buffer.writeln(
          '  processData: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    final controlReferenceTemplateVal = controlReferenceTemplate;
    if (controlReferenceTemplateVal != null) {
      final val = controlReferenceTemplateVal;
      if (val is Uint8List) {
        buffer.writeln('  controlReferenceTemplate: ${_hex(val)},');
      } else {
        buffer.writeln(
          '  controlReferenceTemplate: ${val.toString().replaceAll("\n", "\n  ")},',
        );
      }
    }
    buffer.write(')');
    return buffer.toString();
  }
}

dynamic decodeSgpUniversal(dynamic data) {
  final Asn1Node node = (data is Uint8List)
      ? SimpleAsn1Reader(data).readNext()!
      : data;
  switch (node.tag) {
    case 0x61:
      return CountryName.fromAsn1(node);
    case 0x62:
      return AdministrationDomainName.fromAsn1(node);
    case 0xA0:
      return ContactPcmpResponse_contactPcmpResponseOk.fromAsn1(node);
    case 0xA1:
      return E4EResponse_resultData.fromAsn1(node);
    case 0xA2:
      return RemoteProfileProvisioningResponse.fromAsn1(node);
    case 0xA3:
      return E4ERequest_enableProfile.fromAsn1(node);
    case 0xA4:
      return E4EResponse_resultData_pollRpmPackageResponse.fromAsn1(node);
    case 0xA5:
      return E4EResponse_resultData_confirmDownloadResponse.fromAsn1(node);
    case 0xA6:
      return RpmCommand_rpmCommandDetails_contactPcmp.fromAsn1(node);
    case 0xA9:
      return E4ERequest_pollRpmPackage.fromAsn1(node);
    case 0xAA:
      return E4ERequest_confirmRpmPackage.fromAsn1(node);
    case 0xE0:
      return ISDRProprietaryApplicationTemplate.fromAsn1(node);
    case 0xE1:
      return RefArDo_refDo.fromAsn1(node);
    case 0xE2:
      return RefArDo.fromAsn1(node);
    case 0xE3:
      return ProfileInfo.fromAsn1(node);
    case 0xE4:
      return E4EResponse.fromAsn1(node);
    case 0xBF20:
      return GetEuiccInfo1Request.fromAsn1(node);
    case 0xBF21:
      return PrepareDownloadResponse.fromAsn1(node);
    case 0xBF22:
      return GetEuiccInfo2Request.fromAsn1(node);
    case 0xBF23:
      return InitialiseSecureChannelRequest.fromAsn1(node);
    case 0xBF24:
      return ConfigureISDPRequest.fromAsn1(node);
    case 0xBF25:
      return StoreMetadataRequest.fromAsn1(node);
    case 0xBF26:
      return ReplaceSessionKeysRequest.fromAsn1(node);
    case 0xBF27:
      return ProfileInstallationResultData.fromAsn1(node);
    case 0xBF28:
      return ListNotificationResponse.fromAsn1(node);
    case 0xBF29:
      return SetNicknameResponse.fromAsn1(node);
    case 0xBF2A:
      return UpdateMetadataRequest.fromAsn1(node);
    case 0xBF2B:
      return RetrieveNotificationsListResponse.fromAsn1(node);
    case 0xBF2D:
      return ProfileInfoListResponse.fromAsn1(node);
    case 0xBF2E:
      return GetEuiccChallengeResponse.fromAsn1(node);
    case 0xBF2F:
      return NotificationMetadata.fromAsn1(node);
    case 0xBF30:
      return NotificationSentResponse.fromAsn1(node);
    case 0xBF31:
      return EnableProfileResponse.fromAsn1(node);
    case 0xBF32:
      return DisableProfileResponse.fromAsn1(node);
    case 0xBF33:
      return DeleteProfileResponse.fromAsn1(node);
    case 0xBF34:
      return EuiccMemoryResetResponse.fromAsn1(node);
    case 0xBF36:
      return BoundProfilePackage.fromAsn1(node);
    case 0xBF37:
      return ProfileInstallationResult.fromAsn1(node);
    case 0xBF38:
      return AuthenticateServerResponse.fromAsn1(node);
    case 0xBF39:
      return InitiateAuthenticationResponse.fromAsn1(node);
    case 0xBF3A:
      return GetBoundProfilePackageResponse.fromAsn1(node);
    case 0xBF3B:
      return AuthenticateClientResponseEs9.fromAsn1(node);
    case 0xBF3C:
      return EuiccConfiguredDataResponse.fromAsn1(node);
    case 0xBF3D:
      return HandleNotification.fromAsn1(node);
    case 0xBF3E:
      return GetEuiccDataResponse.fromAsn1(node);
    case 0xBF3F:
      return SetDefaultDpAddressResponse.fromAsn1(node);
    case 0xBF40:
      return AuthenticateClientResponseEs11.fromAsn1(node);
    case 0xBF41:
      return CancelSessionResponseEs9.fromAsn1(node);
    case 0xBF42:
      return LpaeActivationResponse.fromAsn1(node);
    case 0xBF43:
      return GetRatResponse.fromAsn1(node);
    case 0xBF44:
      return LoadRpmPackageResult.fromAsn1(node);
    case 0xBF45:
      return VerifySmdsResponseRequest.fromAsn1(node);
    case 0xBF46:
      return CheckEventResponse.fromAsn1(node);
    case 0xBF4A:
      return AlertData.fromAsn1(node);
    case 0xBF4B:
      return VerifyDeviceChangeResponse.fromAsn1(node);
    case 0xBF4C:
      return ConfirmDeviceChangeResponse.fromAsn1(node);
    case 0xBF4D:
      return PrepareDeviceChangeResponse.fromAsn1(node);
    case 0xBF60:
      return VerifySmdpResponseRequest.fromAsn1(node);
